$$('#players button').forEach(b=>b.onclick=()=>{if(b.dataset.value==='2'&&matchMedia('(pointer:coarse)').matches){showDialog('<div class="badge">LOCAL MULTIPLAYER</div><h2>같이 달리기는 키보드로!</h2><p>한 컴퓨터에서 두 사람이 키보드를 나눠 쓰는 모드야.<br>모바일에서는 혼자 달리기를 즐겨줘.<br>다른 기기와 연결하는 온라인 대전은 아직 지원하지 않아.</p><button class="primary" data-close>알겠어</button>');return}config.players=Number(b.dataset.value);updateSetup()});
