function showDialog(html){$('#dialog').innerHTML=html;$('#overlay').hidden=false;$$('[data-close]').forEach(b=>b.onclick=()=>$('#overlay').hidden=true)}
$('#instructions').onclick=()=>showDialog('<div class="badge">HOW TO PANG</div><h2>코너를 돌면, 팡!</h2><p>가속은 자동이야. 좌우로 방향을 잡아줘.<br>조향하면서 드리프트를 누르면 게이지가 차올라.<br>충전되면 <b>ϟ</b> 버튼으로 부스터를 사용할 수 있어.</p><table><tr><td>1P 조향 / 드리프트</td><td>← → / SPACE</td></tr><tr><td>1P 아이템 / 부스터</td><td>1 · 2 / 3</td></tr><tr><td>2P 조향 / 드리프트</td><td>A · D / SHIFT</td></tr><tr><td>2P 아이템 / 부스터</td><td>Q · E / R</td></tr></table><p>아이템전: ? 박스를 지나고 아이템 버튼을 눌러봐.<br>스피드전: 공격 없이 드리프트와 부스터로 승부!<br>3바퀴를 먼저 완주하면 승리.<br>같이 달리기는 한 컴퓨터에서만 가능해.</p><button class="primary" data-close>준비됐어!</button>');
function clearInput(){keys.clear();touch.clear();$$('.pressed').forEach(b=>b.classList.remove('pressed'));input.forEach(x=>{x.steer=0;x.drift=false})}
function start(){race=new Race(config);screen='race';doneShown=false;$('#lobby').hidden=true;$('#hud').hidden=false;$('#overlay').hidden=true;document.body.classList.toggle('twoPlayer',config.players===2);$('#secondHelp').hidden=config.players!==2;$('#mapTitle').textContent=worlds[config.track].name;$('#raceMode').textContent=config.mode==='item'?'아이템전':'스피드전';$('#minimap').hidden=config.players===2;$('#item0').hidden=$('#item1').hidden=config.mode==='speed';clearInput();beep(440,.15)}
$('#start').onclick=start;
function menu(){screen='lobby';race=null;$('#lobby').hidden=false;$('#hud').hidden=true;$('#overlay').hidden=true;document.body.classList.remove('twoPlayer');clearInput();updateSetup()}
function pause(){if(!race||race.state==='done')return;if(race.state==='paused'){race.state=race.beforePause;$('#overlay').hidden=true;return}race.beforePause=race.state;race.state='paused';clearInput();showDialog('<div class="badge">TAKE A LITTLE BREAK</div><h2>잠깐, 쉬어가기</h2><p>준비되면 다시 달려볼까?</p><button id="resume" class="primary">계속 달리기</button><button id="retry">다시 시작</button><button id="quit">로비로</button>');$('#resume').onclick=pause;$('#retry').onclick=start;$('#quit').onclick=menu}
$('#pause').onclick=pause;
function action(key,p=0){if(!race||race.state!=='racing')return;if(key==='item0')race.use(race.cars[p],0);if(key==='item1')race.use(race.cars[p],1);if(key==='boost')race.boost(race.cars[p])}
addEventListener('keydown',e=>{if(screen!=='race')return;if(['ArrowLeft','ArrowRight','Space','ShiftLeft','ShiftRight','KeyA','KeyD','KeyQ','KeyE','KeyR','Digit1','Digit2','Digit3','Escape'].includes(e.code))e.preventDefault();if(e.repeat)return;keys.add(e.code);if(e.code==='Escape')pause();const acts={Digit1:['item0',0],Digit2:['item1',0],Digit3:['boost',0],KeyQ:['item0',1],KeyE:['item1',1],KeyR:['boost',1]};if(acts[e.code]&&(acts[e.code][1]===0||config.players===2))action(...acts[e.code])});addEventListener('keyup',e=>keys.delete(e.code));
$$('[data-key]').forEach(b=>{const held=new Set();b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);held.add(e.pointerId);b.classList.add('pressed');touch.add(b.dataset.key);action(b.dataset.key)});const release=e=>{held.delete(e.pointerId);if(!held.size){touch.delete(b.dataset.key);b.classList.remove('pressed')}};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release)});
addEventListener('blur',()=>{clearInput();if(race&&race.state!=='paused'&&race.state!=='done')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(race&&race.state!=='paused'&&race.state!=='done')pause()}});
function controls(){input[0].steer=Number(keys.has('ArrowRight')||touch.has('right'))-Number(keys.has('ArrowLeft')||touch.has('left'));input[0].drift=keys.has('Space')||touch.has('drift');input[1].steer=Number(keys.has('KeyD'))-Number(keys.has('KeyA'));input[1].drift=keys.has('ShiftLeft')||keys.has('ShiftRight')}
function toast(text){$('#message').textContent=text;$('#message').style.opacity=1;toastTimer=2.1;beep(650,.075,.025)}
function minimap(){const tr=race.tr,xs=tr.raw.map(p=>p.x),zs=tr.raw.map(p=>p.z),minX=Math.min(...xs),minZ=Math.min(...zs),sx=Math.max(...xs)-minX,sz=Math.max(...zs)-minZ,k=108/Math.max(sx,sz),px=x=>(x-minX-sx/2)*k+70,pz=z=>70-(z-minZ-sz/2)*k;mctx.clearRect(0,0,140,140);mctx.lineWidth=6;mctx.strokeStyle='#ffffff80';mctx.lineJoin='round';mctx.beginPath();tr.raw.forEach((p,i)=>i?mctx.lineTo(px(p.x),pz(p.z)):mctx.moveTo(px(p.x),pz(p.z)));mctx.closePath();mctx.stroke();for(const c of [...race.cars].reverse()){mctx.fillStyle=chars[c.char].color;mctx.strokeStyle='#2a2542';mctx.lineWidth=2;mctx.beginPath();mctx.arc(px(c.x),pz(c.z),c.human?6:4,0,Math.PI*2);mctx.fill();mctx.stroke()}}
function hud(){const c=race.cars[0],ranking=race.ranking();$('#rank').textContent=ranking.indexOf(c)+1;$('#lap').textContent=c.lap;$('#speed').textContent=Math.round(c.v*.83);$('#charge').style.width=c.charge+'%';$('#chargeLabel').textContent=c.readyBoost?'BOOST × '+c.readyBoost:'DRIFT → BOOST';$('.boost').style.opacity=c.readyBoost?1:.4;$('#item0').textContent=icons[c.items[0]]||'—';$('#item1').textContent=icons[c.items[1]]||'—';$('#item0').disabled=!c.items[0];$('#item1').disabled=!c.items[1];$('#countdown').textContent=race.state==='countdown'?Math.ceil(race.count):'';if(race.state==='countdown'&&Math.ceil(race.count)!==hud.lastCount){hud.lastCount=Math.ceil(race.count);beep(340+hud.lastCount*80,.15)}if(frame%5===0)minimap();for(const ev of race.events.splice(0)){if(ev.text==='done'){results();return}if(ev.id===0)toast(ev.text)}if(c.finished&&race.state!=='done'&&config.players===2)$('#countdown').textContent='P1 FINISH';}
function results(){if(doneShown)return;doneShown=true;clearInput();const ranking=race.ranking(),rank=ranking.indexOf(race.cars[0])+1;let best=null,key='pang-best-'+config.track+'-'+config.mode;try{best=Number(localStorage.getItem(key))||null;if(!best||race.cars[0].finishTime<best)localStorage.setItem(key,race.cars[0].finishTime)}catch{};showDialog('<div class="badge">FINISH / '+worlds[config.track].en+'</div><div class="finishRank">'+rank+'<span style="font-size:25px">위</span></div><h2>'+(rank===1?'오늘의 주인공!':'끝까지 달렸어!')+'</h2><p>'+time(race.cars[0].finishTime)+' · '+(config.mode==='item'?'아이템전':'스피드전')+(best?' · 이전 최고 '+time(best):'')+'</p><table>'+ranking.map((c,i)=>'<tr class="'+(c.human?'best':'')+'"><td>'+(i+1)+'</td><td>'+(c.human?(c.id===0?'YOU':'PLAYER 2'):chars[c.char].name)+'</td><td>'+(c.finished?time(c.finishTime):'주행 중')+'</td></tr>').join('')+'</table><button id="again" class="primary">한 번 더 달리기</button><button id="home">다른 트랙 고르기</button>');$('#again').onclick=start;$('#home').onclick=menu;beep(880,.3)}
function renderSplit(){const wide=W>H;const rw=wide?W/2:W,rh=wide?H:H/2;for(let i=0;i<2;i++){ctx.save();ctx.beginPath();ctx.rect(wide?i*rw:0,wide?0:i*rh,rw,rh);ctx.clip();ctx.translate(wide?i*rw:0,wide?0:i*rh);render(ctx,rw,rh,race.tr,race.cars,race.cars[i],{mode:config.mode,boxes:race.boxes,hazards:race.hazards,time:race.elapsed});ctx.fillStyle='#211d38c9';ctx.fillRect(12,rh-70,rw-24,46);ctx.fillStyle='#fff';ctx.font='800 12px sans-serif';ctx.textAlign='left';const c=race.cars[i];ctx.fillText((i?'P2':'P1')+' · '+(race.ranking().indexOf(c)+1)+'위  |  LAP '+c.lap+'/3  |  '+Math.round(c.v*.83)+' km/h',25,rh-48);ctx.font='11px sans-serif';ctx.fillText('BOOST '+c.readyBoost+'   '+c.items.map(x=>icons[x]).join('  ')+(c.finished?'  FINISH!':''),25,rh-31);ctx.restore()}ctx.strokeStyle='#ede5ff';ctx.lineWidth=3;ctx.beginPath();if(wide){ctx.moveTo(W/2,0);ctx.lineTo(W/2,H)}else{ctx.moveTo(0,H/2);ctx.lineTo(W,H/2)}ctx.stroke()}
function loop(ts){const dt=Math.min((ts-last)/1000||0,.04);last=ts;frame++;if(screen==='lobby'){previewTime+=dt;const p=preview.at(previewTime*35+preview.length*.12);const c={...p,char:config.char,id:0,heading:p.yaw,lastS:p.s,v:80,human:false,charge:0,boost:0,shield:0,drift:0,invuln:0,ink:0};ctx.save();if(W>700){ctx.beginPath();ctx.rect(0,0,W,H);ctx.clip()}render(ctx,W,H,preview,[c],c,{mode:'speed',time:previewTime});const g=ctx.createLinearGradient(0,0,W,0);g.addColorStop(0,'#f9f6efe8');g.addColorStop(W>700?.37:.7,'#f9f6ef11');g.addColorStop(1,'#f9f6ef30');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.restore()}else if(race){controls();race.step(dt,input);if(config.players===2)renderSplit();else {const vw=Math.min(W,520),left=(W-vw)/2;ctx.fillStyle='#e9e4ef';ctx.fillRect(0,0,W,H);if(W>520){ctx.fillStyle='#c0b3d0';ctx.font='800 11px sans-serif';ctx.textAlign='center';ctx.fillText('PANGPANG',left/2,H*.47);ctx.fillText('RACING CLUB',W-left/2,H*.47);ctx.fillText('← → 조향',left/2,H*.51);ctx.fillText('SPACE 드리프트',W-left/2,H*.51)}ctx.save();ctx.beginPath();ctx.rect(left,0,vw,H);ctx.clip();ctx.translate(left,0);render(ctx,vw,H,race.tr,race.cars,race.cars[0],{mode:config.mode,boxes:race.boxes,hazards:race.hazards,time:race.elapsed});ctx.restore();}hud();if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#message').style.opacity=0}}requestAnimationFrame(loop)}requestAnimationFrame(loop);
